import React, { useState } from 'react';

function AquariumForm({ onAquariumCreate }) {
    const [name, setName] = useState('');
    const [photoUrl, setPhotoUrl] = useState('');
    const [volume, setVolume] = useState('');
    const [type, setType] = useState('Planted');
    const [targetParameters, setTargetParameters] = useState(''); 
    const [initialSetupNotes, setInitialSetupNotes] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!name || !volume) {
            setError('El nombre y el volumen son obligatorios.');
            return;
        }
        setError('');
        const newAquarium = {
            id: Date.now().toString(), 
            name,
            photoUrl,
            volume: parseFloat(volume),
            type,
            targetParameters,
            initialSetupNotes
        };
        onAquariumCreate(newAquarium);
        setName('');
        setPhotoUrl('');
        setVolume('');
        setType('Planted');
        setTargetParameters('');
        setInitialSetupNotes('');
    };

    return (
        <form onSubmit={handleSubmit} style={{ marginBottom: '28px', background: 'rgba(255,255,255,0.85)', borderRadius: '18px', boxShadow: '0 2px 12px 0 rgba(79,140,255,0.07)', padding: '24px 18px' }}>
            <h3>Nuevo Acuario</h3>
            {error && <div style={{color:'#e11d48', marginBottom:'12px', fontWeight:500, fontSize:'1rem'}}>{error}</div>}
            <div>
                <label>Nombre</label>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Ej: Acuario principal" required />
            </div>
            <div>
                <label>URL de la foto</label>
                <input type="text" value={photoUrl} onChange={(e) => setPhotoUrl(e.target.value)} placeholder="https://..." />
            </div>
            <div>
                <label>Volumen (litros)</label>
                <input type="number" value={volume} onChange={(e) => setVolume(e.target.value)} min="1" step="0.1" placeholder="Ej: 120" required />
            </div>
            <div>
                <label>Tipo</label>
                <select value={type} onChange={(e) => setType(e.target.value)}>
                    <option value="Planted">Plantado</option>
                    <option value="Community">Comunitario</option>
                    <option value="Marine">Marino (solo peces)</option>
                    <option value="Reef">Reef (marino con corales)</option>
                    <option value="Brackish">Agua salobre</option>
                    <option value="Coldwater">Agua fría</option>
                    <option value="Species-specific">Específico (ej: Betta, Gambas)</option>
                    <option value="Other">Otro</option>
                </select>
            </div>
            <div>
                <label>Parámetros objetivo</label>
                <input type="text" value={targetParameters} onChange={(e) => setTargetParameters(e.target.value)} placeholder="Ej: pH 7, Temp 25ºC" />
            </div>
            <div>
                <label>Notas de configuración inicial</label>
                <textarea value={initialSetupNotes} onChange={(e) => setInitialSetupNotes(e.target.value)} placeholder="Observaciones, equipamiento, etc." />
            </div>
            <button type="submit">Añadir acuario</button>
        </form>
    );
}

export default AquariumForm;
